	slices.SortFunc(fresh, func(a, b msgKey) int { return o.entries[a].first.compare(o.entries[b].first) })
	skip := make(map[msgKey]bool, len(fresh)-room)
	for _, k := range fresh[room:] {
		skip[k] = true
	}
	t.mergeSkipping(o, skip)
}

