		{"timestamp a number", `{"type":"assistant","timestamp":123,"message":{"id":"m","model":"m",` + usageObj + `}}`, kindUsage, "", nil},
		{"timestamp null", `{"type":"assistant","timestamp":null,"message":{"id":"m","model":"m",` + usageObj + `}}`, kindUsage, "", nil},
